Pass 4 is in. I'll compare original and start log-probs on identical tokens for each event type: first-exit `</think>`, re-close `</think>`, the first revert line in each text's first answer segment, all revert lines, and ordinary answer and thinking tokens. A large positive start-minus-original difference at reverts would support H-rev; a near-zero one rejects it.

```python
# Hypothesis H-rev: start (E2/E3/3109) raises lp of revert tokens ('Wait','Actually','Hmm' at line start) in the answer vs original; re-closes are E2-driven.
tok4 = np.load('/work/fwd_4/tokens.npy'); lp4 = np.load('/work/fwd_4/token_logprobs.npy'); lp3 = np.load('/work/fwd_3/token_logprobs.npy')
print('tokens identical:', np.array_equal(tok4, toks3))
REVW = {'Wait','Actually','Hmm'}
dec_cache = {}
def dec(t):
    if t not in dec_cache: dec_cache[t] = tok.decode([t])
    return dec_cache[t]
cat = collections.defaultdict(list)
for i in range(40):
    n = lens3[i]; tk = toks3[i,:n].tolist()
    th = [t for t,x in enumerate(tk) if x==TH]
    first = th[0] if th else n
    seen_first_rev=False
    for t in range(1,n):
        d = (lp3[i,t]-lp4[i,t], lp3[i,t], lp4[i,t])
        if tk[t]==TH:
            cat['exit1' if t==first else 'reclose'].append(d); continue
        if tk[t]==IMEND: cat['im_end'].append(d); continue
        if t>first:
            w=dec(tk[t]).strip()
            if w in REVW and '\n' in dec(tk[t-1]):
                cat['rev_all'].append(d)
                if not seen_first_rev and (len(th)<2 or t<th[1]): cat['rev_first_seg1'].append(d); seen_first_rev=True
            else: cat['answer_other'].append(d)
        else:
            w=dec(tk[t]).strip()
            if w in REVW and '\n' in dec(tk[t-1]): cat['think_rev'].append(d)
            else: cat['think_other'].append(d)
for k,v in cat.items():
    a=np.array(v); print(f'{k:16s} n={len(a):6d} mean d={a[:,0].mean():+.3f} med d={np.median(a[:,0]):+.3f}  lp_start={a[:,1].mean():+.3f} lp_orig={a[:,2].mean():+.3f}')
```

The kernel still has the pass-3 phase-analysis tools (`lda_fit`, `lda_eval`, `err_breakdown`, `u_dir`, `HS3`). I'll print their source so the early-layer analysis uses the same definitions (RMS-normalisation, shrinkage, the loop-position marker, the held-out text split). That way the h4/h8 results are directly comparable with the h10 to h23 numbers in my notes.

```python
# Hypothesis: reuse session-2 phase-LDA tools; print their source to apply them to pass-4 hidden states.
for fn in ['lda_fit','lda_eval','err_breakdown','proj_stats','spans']:
    f=globals().get(fn)
    if callable(f):
        try: print(inspect.getsource(f)[:1500])
        except Exception as e: print(fn, 'no source', e)
    else: print(fn, type(f).__name__, (len(f) if hasattr(f,'__len__') else ''))
print(type(HS3), getattr(HS3,'shape',None), 'tr/te', len(tr_ids), len(te_ids), tr_ids[:5])
```

This is the useful view. Just before re-closes, every layer's phase readout says "answer" for 99 to 100% of positions, held-out texts included. Just before first exits it wrongly says "answer" for 8 to 28% of positions on training texts and 22 to 51% on held-out texts. So the readout is reliable where the gate must act, and the risk is weakening the first exit. With only 30 training texts the LDA probably overfits. I'll sweep stronger shrinkage and the threshold. I'm looking for a setting where pre-exit misreads fall below about 5% while pre-reclose positions stay above about 95% on held-out texts. If one exists, a soft gate on E2 in the answer phase is feasible, and the open question becomes what the push should do there instead of re-closing.

```python
# Hypothesis: with stronger shrinkage and a shifted threshold, one layer separates pre-exit (thinking) from pre-reclose (answer) with margin on held-out texts.
def scores(HS, li, ids, which, w):
    v=[]
    for i in ids:
        pos=pre_event_positions(i,which)
        if len(pos): v.append(rmsn(HS[i,li,pos])@w)
    return np.concatenate(v) if v else np.array([])
for name,HS,li in [('h7',HS4,2),('h11',HS3,1),('h13',HS3,2),('h15',HS3,4),('h23',HS3,5)]:
    for lamfrac in [0.05, 0.5, 5.0]:
        Xtr,Ytr,_=collect(HS,li,tr_ids); w,c=lda(Xtr,Ytr,lamfrac)
        # threshold chosen on TRAIN pre-reclose vs pre-exit: the 5th percentile of train pre-reclose scores
        rtr=scores(HS,li,tr_ids,'reclose',w); etr=scores(HS,li,tr_ids,'exit1',w)
        thr=np.quantile(rtr,0.05)
        rte=scores(HS,li,te_ids,'reclose',w); ete=scores(HS,li,te_ids,'exit1',w)
        # also generic held-out thinking false positive at that threshold
        Xte,Yte,Lte=collect(HS,li,te_ids,step=4); p=Xte@w
        print(f'{name} lam{lamfrac}: thr@5%reclose-tr | exit misread tr {(etr>thr).mean():.2f} te {(ete>thr).mean():.2f} | reclose hit te {(rte>thr).mean():.2f} | heldout think FP {(p[Yte==0]>thr).mean():.3f} thinking-loop FP {(p[(Yte==0)&Lte]>thr).mean():.3f} answer hit {(p[Yte==1]>thr).mean():.3f}')
```

The w7 score is not a pure count. In normal answers that close once, it is high for math write-ups and code (exceeding 15 at 20 to 86% of positions), while IF prose stays low. So it mixes "closes seen" with answer style, and a gate on it would act inside ordinary math and code answers.

The step at each `</think>` points to a cleaner component. In degenerate cycles the text before and after a close looks alike, so the jump in h7 across a close there isolates the increment written when another `</think>` enters the context. I'll estimate that increment direction from closes 3 and later (mean of the 20 tokens after minus the 20 before), fitted on training texts, then project all positions on it. If this projection grows with the number of closes but stays low in normal single-close math and code answers, it is the count signal without the style confound.

```python
# Hypothesis: the jump direction across late </think> tokens (similar content before/after) isolates a content-free 'closes seen' signal.
def step_dir(ids, kmin=3, layer_idx=2, HS=HS4, W=20):
    acc=[]; 
    for i in ids:
        n=lens3[i]; tk=toks3[i,:n]; th=np.where(tk==TH)[0]
        if len(th)<kmin: continue
        X=rmsn(HS[i,layer_idx,:n])
        for t in th[kmin-1:]:
            if t-W<0 or t+2+W>n: continue
            acc.append(X[t+2:t+2+W].mean(0)-X[t-W:t].mean(0))
    return np.mean(acc,0), len(acc)
d7, nd = step_dir(tr_ids); d7u = d7/np.linalg.norm(d7)
print('n steps', nd, ' cos(d7u, w7)', float(d7u@w7/np.linalg.norm(w7)))
def score_report(dvec, layer_idx=2, HS=HS4, ids=range(40)):
    grp=collections.defaultdict(list)
    for i in ids:
        n=lens3[i]; tk=toks3[i,:n]; th=np.where(tk==TH)[0]
        s=rmsn(HS[i,layer_idx,:n])@dvec
        lab=labels[i]; grp['think'].append(s[lab==0])
        if len(th)==1: grp['single:'+idx3[i][1]].append(s[th[0]+1:])
        b=list(th)+[n]
        for k in range(len(th)-1 if len(th)>1 else 0):
            kk=min(k+1,4); grp[f'pre#{k+2 if k+2<5 else "5+"}'].append(s[max(0,b[k+1]-20):b[k+1]])
            grp[f'seg{kk}{"+" if kk==4 else ""}(multi)'].append(s[b[k]+1:b[k+1]])
    for g in sorted(grp):
        v=np.concatenate(grp[g])
        print(f'  {g:18s} n={len(v):6d} p10 {np.quantile(v,.1):6.2f} p50 {np.median(v):6.2f} p90 {np.quantile(v,.9):6.2f} p99 {np.quantile(v,.99):6.2f}')
score_report(d7u, ids=te_ids)
```
